/** SessionStart, after the standing directive. */
export function sessionBlock(cadence: string): string {
  return [
    '[Eklavya] Delegation is on for this session (delegate_work). For a code change across several files:',
    `  - An agent run in the background builds it, with ${BRIEF}.`,
    `  - ${asking(cadence)} Write the task answer last.`,
  ].join('\n');
}

/** UserPromptSubmit, next to a task-sized prompt: the moment the model decides how to build. */
export function promptLine(cadence: string): string {
  return `[Eklavya] If this asks for a code change across several files, do not build it inline: start an agent in the background with ${BRIEF}. ${asking(cadence)}`;
}

// prompt-submit-nudge.ts
// The task-time seam for delegation. The session-start block is far back by
// the time a task arrives. Said here, the contract sits next to the plan it is
// about, before the first edit.
if (resolved.config.delegate_work && typeof input.prompt === 'string') {
  const text = input.prompt.trim();
  if (text.length >= TASK_PROMPT_CHARS && !SLASH.test(text) && !HOST_PROMPT.test(text)) {
    context.push(promptLine(resolved.config.cadence));
  }
}

