export const MCQ_OPTION_COUNT = 4;

/**
 * Which slot the correct option goes in, derived from the question itself.
 */
function hash(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

export function answerPosition(seed: string): number {
  return (hash(seed) % MCQ_OPTION_COUNT) + 1;
}

