export async function page(after?: string, limit = 20) {
  const rows = await db.query(
    'SELECT * FROM posts WHERE ($1::bigint IS NULL OR id < $1) ORDER BY id DESC LIMIT $2',
    [after ?? null, limit + 1],
  );
  return { items: rows.slice(0, limit), next: rows.length > limit ? rows[limit - 1].id : null };
}

