/**
 * A busy transaction has already rolled back, so retrying is safe for writes
 * as well as reads.
 */
export function retryOnBusy<T>(fn: () => T, attempts = 5): T {
  let lastError: unknown;
  for (let i = 0; i < attempts; i++) {
    try {
      return fn();
    } catch (err) {
      if (!isBusy(err)) throw err;
      lastError = err;
      sleepBriefly(i);
    }
  }
  throw lastError;
}

